CREATE OR REPLACE FUNCTION cp7_sku_conversion.automatic_cost_unit_v5(p_lot uuid, p_product uuid, p_location uuid, p_grade text)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if cp7_sku_conversion.automatic_scope_v5(p_product,p_location,p_grade)
  and cp7_sku_conversion.automatic_root_v5(p_lot)then
