 select *into strict s from erp.be_conversion_sources_v1 where conversion_id=c.id;
 select *into g from cp7_sku_conversion.legacy_groups_v4 where group_id=c.id;
 if (f.phase='POST'and c.status is distinct from 'POSTED')
  or(f.phase='REVERSE'and c.status is distinct from 'REVERSED')
  or(f.phase='POST'and(g.group_id is null or not exists(
    select 1 from cp7_sku_conversion.valuation_postings_v2 v where v.group_id=c.id and v.phase='POST')))
  or(g.group_id is not null and not exists(select 1 from cp7_sku_conversion.valuation_postings_v2 v
    where v.group_id=c.id and v.phase=f.phase))then
  raise exception 'CP7_SKU_AUTOMATIC_NATIVE_AND_ECONOMIC_RESULT_REQUIRED';end if;
 insert into cp7_sku_conversion.automatic_admissions_v5(conversion_id,phase,rework_id,context_proof,conversion_proof)
 values(c.id,f.phase,f.rework_id,to_jsonb(f),jsonb_build_object(
  'native',to_jsonb(c),'source',to_jsonb(s),'legacy',to_jsonb(g),
  'valuation',(select to_jsonb(q)from cp7_sku_conversion.valuation_quotes_v2 q where q.group_id=c.id)));
 delete from cp7_sku_conversion.automatic_context_v5
  where backend_pid=f.backend_pid and transaction_id=f.transaction_id and conversion_id=f.conversion_id;
end $function$

cp7_sku_conversion.pool_quote_v2(uuid,uu:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.pool_quote_v2(p_product uuid, p_location uuid, p_grade text DEFAULT 'GRADE_A'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare v_qty numeric(20,6);v_base numeric(24,6);v_adjust numeric(24,6);v_value numeric(24,6);v_attr numeric(24,6);v_unknown boolean;v_revision text;v_automatic boolean;v_cost_pending boolean;
begin
 if p_product is null or p_location is null or p_grade is distinct from 'GRADE_A' then raise exception 'CP7_SKU_VALUE_SCOPE_REQUIRED';end if;
 v_automatic:=cp7_sku_conversion.automatic_scope_v5(p_product,p_location,p_grade);
 with components as materialized(
  select c.*,h.cost_state,l.po_id root_po_id
  from cp7_sku_conversion.pool_components_v2(p_product,p_location,p_grade)c
  join erp.fg_lots l on l.id=c.root_lot_id
  left join erp.hpp_versions h on h.id=c.hpp_version_id
 ), totals as(
  select coalesce(sum(component_units),0)::numeric qty,coalesce(sum(value),0)::numeric value,
   coalesce(bool_or(component_units< -0.000000000001 or hpp_version_id is null or unit_value is null or cost_state='ESTIMATED'
    or erp.bd_lot_laundry_unknown_v1(root_lot_id)
    or(root_po_id is not null and not exists(select 1 from erp.get_hpp_completeness(root_po_id)z where z.pending_reason_count=0))),false) unknown
  from components
 )select qty,round(value,6),unknown into v_qty,v_value,v_unknown from totals;
 if v_automatic and exists(
  select 1 from cp7_sku_conversion.pool_components_v2(p_product,p_location,p_grade)c
  join erp.fg_lots l on l.id=c.root_lot_id left join erp.hpp_versions h on h.id=c.hpp_version_id
  where c.component_units< -0.000000000001 or c.hpp_version_id is null or c.unit_value is null
   or c.unit_value::text in('NaN','Infinity','-Infinity')
   or(l.po_id is not null and not exists(select 1 from erp.production_orders p where p.id=l.po_id))
   or(l.po_id is null and(h.cost_state='ESTIMATED'or erp.bd_lot_laundry_unknown_v1(l.id)))
 )then raise exception 'CP7_SKU_AUTOMATIC_PRESENT_NUMERIC_PO_COMPONENTS_REQUIRED';end if;
 if v_unknown and not v_automatic then raise exception 'CP7_SKU_POOL_HPP_UNKNOWN: seluruh komponen ekonomi termasuk reservasi harus diketahui';end if;
 v_base:=v_value;
 select coalesce(sum(c.value),0)into v_adjust from cp7_sku_conversion.pool_cost_components_v3(p_product,p_location,p_grade)c;
 v_value:=round(v_base+v_adjust,6);
 if v_automatic then
  select coalesce(bool_or((c.source_revision->>'accounting_only')::boolean is true
   and(c.source_revision->>'final_cost_ready')::boolean is not true),false)
  into v_cost_pending from cp7_sku_conversion.pool_cost_components_v3(p_product,p_location,p_grade)c;
  v_unknown:=v_unknown or v_cost_pending;
 end if;
 if v_value<0 then raise exception 'CP7_SKU_POOL_VALUE_NEGATIVE: nilai efektif persediaan tidak boleh negatif';end if;
 select coalesce(sum(a.value),0)into v_attr from cp7_sku_conversion.pool_attribution_v2(p_product,p_location,p_grade)a;
 if round(v_attr,6)is distinct from v_value then raise exception 'CP7_SKU_POOL_ATTRIBUTION_MISMATCH';end if;
 select md5(jsonb_build_object('product',p_product,'location',p_location,'grade',p_grade,'qty',v_qty,'base',v_base,'adjust',v_adjust,
  'components',(select coalesce(jsonb_agg(to_jsonb(c)order by c.root_lot_id),'[]'::jsonb)
   from cp7_sku_conversion.pool_components_v2(p_product,p_location,p_grade)c),
  'cost_components',(select coalesce(jsonb_agg(to_jsonb(c)order by c.root_lot_id),'[]'::jsonb)
   from cp7_sku_conversion.pool_cost_components_v3(p_product,p_location,p_grade)c),
  'cost_events',(select coalesce(jsonb_agg(to_jsonb(e)order by e.recorded_at,e.id),'[]'::jsonb)
   from cp7_sku_conversion.cost_events_v3 e where e.product_id=p_product and e.location_id=p_location and e.quality_grade=p_grade),
  'base_money',(select coalesce(jsonb_agg(to_jsonb(m)order by m.id),'[]')from cp7_sku_conversion.base_money_events_v4 m
   where m.root_lot_id in(select root_lot_id from cp7_sku_conversion.pool_components_v2(p_product,p_location,p_grade))),
  'events',(select coalesce(jsonb_agg(to_jsonb(e)order by e.recorded_at,e.id),'[]'::jsonb)from cp7_sku_conversion.valuation_events_v2 e
   where e.product_id=p_product and e.location_id=p_location and e.quality_grade=p_grade))::text) into v_revision;
 return jsonb_build_object('state',case when v_qty=0 then 'EMPTY'when v_unknown then 'PROVISIONAL'else 'KNOWN'end,'qty',v_qty::text,'value',v_value::text,
  'average',case when v_qty>0 then (v_value/v_qty)::text end,'base_value',v_base::text,'adjustment',v_adjust::text,
  'reserved_included',true,'basis','SKU_LOCATION_GRADE_MOVING_AVERAGE_V2','revision',v_revision)||case when v_automatic then jsonb_build_object('final_cost_ready',not v_unknown)else '{}'::jsonb end;
end $function$

