CREATE OR REPLACE FUNCTION cp7_sku_conversion.post_conversion_money_v3(p_group uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare q cp7_sku_conversion.valuation_quotes_v2%rowtype;c record;cell record;old_units numeric;
 economic_date date;product uuid;
begin
 perform erp.require_internal();perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
 select *into strict q from cp7_sku_conversion.valuation_quotes_v2 where group_id=p_group;
 economic_date:=(q.physical_at at time zone 'Asia/Jakarta')::date;
 for c in select *from cp7_sku_conversion.cost_contributors_v3 where group_id=p_group and po_id is null order by root_lot_id loop
  select *into strict cell from cp7_sku_conversion.cost_money_cells_v3(c.root_lot_id)where product_id=q.source_product_id;
  -- Cost units have just moved; the money still belongs to the old source.
  old_units:=cell.units+c.transfer_units;
  if old_units<=0 or c.transfer_units>old_units
   or(c.transfer_units=old_units and c.transfer_value is distinct from cell.amount)
   or(cell.amount>=0 and(c.transfer_value<0 or c.transfer_value>cell.amount))
   or(cell.amount<0 and(c.transfer_value>0 or c.transfer_value<cell.amount))then
   raise exception 'CP7_SKU_COST_MONEY_TRANSFER_CAPACITY';end if;
  insert into cp7_sku_conversion.cost_money_events_v3(id,kind,source_id,root_lot_id,product_id,amount_delta,revision,source_proof,economic_date)
  values(gen_random_uuid(),'TRANSFER',p_group,c.root_lot_id,q.source_product_id,-c.transfer_value,p_group::text,to_jsonb(c),economic_date),
        (gen_random_uuid(),'TRANSFER',p_group,c.root_lot_id,q.target_product_id,c.transfer_value,p_group::text,to_jsonb(c),economic_date);
 end loop;
 for c in select a.*,l.po_id from cp7_sku_conversion.members_v1 m
  join erp.product_conversion_allocations a on a.conversion_id=m.conversion_id join erp.fg_lots l on l.id=a.destination_lot_id
  where m.group_id=p_group and l.po_id is null order by a.id loop
  insert into cp7_sku_conversion.cost_money_events_v3(id,kind,source_id,root_lot_id,product_id,amount_delta,revision,source_proof,economic_date)
  values(gen_random_uuid(),'ORIGIN',p_group,c.destination_lot_id,q.target_product_id,erp.be_allocation_extra_v1(c.id),
   p_group::text,jsonb_build_object('allocation',to_jsonb(c),'initial_extra',erp.be_allocation_extra_v1(c.id)),economic_date);
 end loop;
 for c in select distinct e.root_lot_id from cp7_sku_conversion.cost_events_v3 e where e.source_type='SKU_CONVERSION'and e.source_id=p_group loop
  perform cp7_sku_conversion.automatic_cost_unit_v5(c.root_lot_id,q.source_product_id,q.location_id,q.quality_grade);
  perform cp7_sku_conversion.automatic_cost_unit_v5(c.root_lot_id,q.target_product_id,q.location_id,q.quality_grade);
 end loop;
end $function$

erp.be_complete_rework_target_v1(uuid):
CREATE OR REPLACE FUNCTION erp.be_complete_rework_target_v1(p_rework uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b erp.be_rework_targets_v1%rowtype;r erp.rework_orders%rowtype;v_own boolean;v_result jsonb;v_automatic_request uuid;
begin
 select * into b from erp.be_rework_targets_v1 where rework_id=p_rework;
 if b.rework_id is null then return;end if;
 select * into r from erp.rework_orders where id=p_rework for update;
 if not r.cost_posted or r.status<>'COMPLETED' then raise exception 'BE_REWORK_NOT_COMPLETE';end if;
 if r.qty_good_returned=0 then return;end if;
 if r.good_fg_lot_id is null then raise exception 'BE_REWORK_GOOD_LOT_MISSING';end if;
 if exists(select 1 from erp.be_conversion_sources_v1 s join erp.product_conversions c on c.id=s.conversion_id
      where s.rework_id=r.id and s.source_lot_id=r.good_fg_lot_id and c.status='POSTED') then return;end if;
 v_own:=not erp.be_in_context_v1();
 if v_own then insert into erp.be_execution_context_v1(backend_pid,transaction_id,request_id) values(pg_backend_pid(),txid_current(),gen_random_uuid());end if;
 v_automatic_request:=gen_random_uuid();
 perform cp7_sku_conversion.automatic_enter_v5(p_rework,'POST',v_automatic_request);
 v_result:=erp.be_post_conversion_v1(jsonb_build_object('source_lot_id',r.good_fg_lot_id,'target_product_id',b.target_product_id,
   'location_id',r.return_fg_location_id,'qty_pcs',r.qty_good_returned,'physical_at',r.completed_at,'reason',b.reason,
   'expected_version',erp.be_source_revision_v1(r.good_fg_lot_id,r.return_fg_location_id)),v_automatic_request,
   case when b.mode='REDYE_SKU' then 'REDYE' else 'REWORK' end,r.id);
 perform cp7_sku_conversion.automatic_leave_v5(p_rework,'POST',v_automatic_request);
 if v_own then delete from erp.be_execution_context_v1 where backend_pid=pg_backend_pid() and transaction_id=txid_current();end if;
end;$function$

erp.be_conversion_preview_v1(jsonb):
CREATE OR REPLACE FUNCTION erp.be_conversion_preview_v1(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare l erp.fg_lots%rowtype;s erp.products%rowtype;t erp.products%rowtype;v_location uuid;v_qty integer;
 v_at timestamptz;v_current numeric;v_dated numeric;v_hpp numeric;v_cost jsonb;v_source_pool jsonb;v_target_pool jsonb;
begin
 perform erp.require_permission('warehouse.brand_conversion.view');
 perform erp._cp3_assert_closed_json_object(p_payload,
   array['source_lot_id','target_product_id','location_id','qty_pcs','physical_at','reason','expected_version'],
   array['source_lot_id','target_product_id','location_id','qty_pcs','physical_at','reason','expected_version','expected_returns'],'konversi');
 perform erp.pocket_period_lock_v1();
 select * into l from erp.fg_lots where id=erp.bd_uuid_v1(p_payload,'source_lot_id',true);
 if l.id is null then raise exception 'BE_SOURCE_NOT_FOUND: lot sumber tidak ditemukan';end if;
 select * into s from erp.products where id=l.product_id for share;
 select * into t from erp.products where id=erp.bd_uuid_v1(p_payload,'target_product_id',true) for share;
 if t.id is null or not t.is_active then raise exception 'BE_TARGET_NOT_ACTIVE: SKU tujuan tidak aktif';end if;
 if t.id=s.id then raise exception 'BE_SAME_SKU: pilih SKU tujuan yang berbeda';end if;
 if not cp7_sku_conversion.manual_allocation_v1(l.id,t.id,(p_payload->>'location_id')::uuid,(p_payload->>'qty_pcs')::int,(p_payload->>'physical_at')::timestamptz) and (t.model_id is distinct from s.model_id or t.size_id is distinct from s.size_id) then
   raise exception 'BE_DIMENSION_MISMATCH: model konstruksi dan ukuran harus tetap';end if;
 v_location:=erp.bd_uuid_v1(p_payload,'location_id',true);
 v_qty:=erp.bd_qty_v1(p_payload->'qty_pcs','qty_pcs');
 v_at:=erp.bd_at_v1(p_payload->>'physical_at','physical_at');
 perform erp.bc_text_v1(p_payload,'reason',true,1000);
 if v_at<l.produced_at then raise exception 'BE_BEFORE_SOURCE: waktu konversi sebelum lot tersedia';end if;
 if v_at<s.effective_from then
  raise exception 'SKU % belum berlaku pada tanggal/jam transaksi %. Berlaku mulai %.',s.sku,v_at,s.effective_from;
 end if;
 if v_at<t.effective_from then
  raise exception 'SKU % belum berlaku pada tanggal/jam transaksi %. Berlaku mulai %.',t.sku,v_at,t.effective_from;
 end if;
 if t.effective_to is not null and v_at>=t.effective_to then
  raise exception 'Versi SKU % sudah berakhir pada %. Gunakan versi SKU yang berlaku pada tanggal/jam transaksi.',t.sku,t.effective_to;
 end if;
 if jsonb_typeof(p_payload->'expected_version') is distinct from 'string'
   or p_payload->>'expected_version' is distinct from erp.be_source_revision_v1(l.id,v_location) then
   raise exception 'STALE_VERSION: stok atau HPP sumber berubah; muat ulang';end if;
 select coalesce(sum(m.qty_signed),0),coalesce(sum(m.qty_signed) filter(where m.physical_at<=v_at),0)
   into v_current,v_dated from erp.fg_stock_movements m
   where m.lot_id=l.id and m.location_id=v_location and m.quality_grade='GRADE_A';
 if v_qty>least(v_current,v_dated) then raise exception 'BE_SOURCE_CAPACITY: jumlah melebihi stok sumber pada tanggalnya';end if;
 select hpp_per_pcs into v_hpp from erp.v_current_hpp where lot_id=l.id;
 if v_hpp is null then raise exception 'BE_SOURCE_HPP_UNKNOWN: nilai sumber belum diketahui';end if;
 v_cost:=case when erp.has_permission('finance.hpp.view') then
   jsonb_build_object('source_unit_hpp',v_hpp::text,'source_value',round(v_hpp*v_qty,2)::text) else '{}'::jsonb end;
 if not cp7_sku_conversion.manual_allocation_v1(l.id,t.id,v_location,v_qty,v_at)then
  v_source_pool:=cp7_sku_conversion.pool_quote_v2(s.id,v_location,'GRADE_A');
  v_target_pool:=cp7_sku_conversion.pool_quote_v2(t.id,v_location,'GRADE_A');
  if (v_source_pool->>'qty')::numeric<v_qty then raise exception 'CP7_SKU_INSUFFICIENT_VALUE_POOL: stok fisik bernilai tidak cukup';end if;
  if erp.has_permission('finance.hpp.view')then
   v_cost:=jsonb_build_object('source_unit_hpp',v_source_pool->>'average',
    'source_value',round(v_qty*(v_source_pool->>'average')::numeric,2)::text,
    'native_physical_value',round(v_hpp*v_qty,2)::text,'basis','SKU_LOCATION_GRADE_MOVING_AVERAGE_V2');
  end if;
 end if;
 return jsonb_build_object('source_lot_id',l.id,'source_product_id',s.id,'target_product_id',t.id,
   'source_sku',s.sku,'target_sku',t.sku,'location_id',v_location,'qty_pcs',v_qty,'physical_at',v_at,
   'source_revision',p_payload->>'expected_version','cost',v_cost)
  ||case when v_source_pool is null then '{}'::jsonb else jsonb_build_object(
   'source_value_revision',v_source_pool->>'revision','target_value_revision',v_target_pool->>'revision')
   ||case when cp7_sku_conversion.automatic_scope_v5(s.id,v_location,'GRADE_A')then jsonb_build_object(
    'source_value_state',v_source_pool->>'state','target_value_state',v_target_pool->>'state',
    'valuation_provisional',v_source_pool->>'state'='PROVISIONAL'or v_target_pool->>'state'='PROVISIONAL')else '{}'::jsonb end
  end;
end;$function$

erp.be_post_conversion_v1(jsonb,uuid,tex:
CREATE OR REPLACE FUNCTION erp.be_post_conversion_v1(p_payload jsonb, p_request uuid, p_origin text DEFAULT 'FG'::text, p_rework uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v jsonb;l erp.fg_lots%rowtype;r jsonb;i integer:=0;v_return uuid;v_qty numeric;v_material uuid;v_dest uuid;v_legacy boolean;v_original_preview jsonb;v_native_request uuid;
begin
 perform erp.require_permission('warehouse.brand_conversion.post');
 if not erp.be_in_context_v1() then raise exception 'BE_FACADE_REQUIRED';end if;
 perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
 select * into l from erp.fg_lots where id=erp.bd_uuid_v1(p_payload,'source_lot_id',true) for update;
 perform cp7_sku_conversion.automatic_assert_native_v5(p_request,p_origin,p_rework,p_payload);
 v:=erp.be_conversion_preview_v1(p_payload);
 v_legacy:=not cp7_sku_conversion.manual_allocation_v1(l.id,(v->>'target_product_id')::uuid,
  (v->>'location_id')::uuid,(v->>'qty_pcs')::int,(v->>'physical_at')::timestamptz);
 if v_legacy then
  if exists(select 1 from cp7_sku_conversion.execution_v1 where backend_pid=pg_backend_pid()and transaction_id=txid_current())then
   raise exception 'CP7_SKU_LEGACY_EXECUTION_CONFLICT';end if;
  select request_id into strict v_native_request from erp.be_execution_context_v1
   where backend_pid=pg_backend_pid()and transaction_id=txid_current();
  v_original_preview:=v;
  insert into cp7_sku_conversion.groups_v1(request_id,actor,payload)values(p_request,erp.current_app_user_id(),p_payload);
  perform cp7_sku_conversion.prepare_valuation_v2(p_request,v);
  insert into cp7_sku_conversion.legacy_groups_v4(group_id,source_lot_id,origin_kind,rework_id,original_preview,
   native_request_id,admission_backend_pid,admission_transaction_id)
  values(p_request,l.id,p_origin,p_rework,v,v_native_request,pg_backend_pid(),txid_current());
  insert into cp7_sku_conversion.execution_v1(backend_pid,transaction_id,group_id,mode,source_lot_id,target_id,location_id,qty,physical_at)
  values(pg_backend_pid(),txid_current(),p_request,'POST',l.id,(v->>'target_product_id')::uuid,
   (v->>'location_id')::uuid,(v->>'qty_pcs')::int,(v->>'physical_at')::timestamptz);
  v:=jsonb_set(v,'{source_revision}',to_jsonb(erp.be_source_revision_v1(l.id,(v->>'location_id')::uuid)));
 end if;
 insert into erp.product_conversions(id,conversion_number,from_product_id,to_product_id,location_id,qty_pcs,conversion_type,
   physical_at,status,conversion_cost_total,notes,created_by)
 values(p_request,'BE-'||p_request::text,l.product_id,(v->>'target_product_id')::uuid,(v->>'location_id')::uuid,
   (v->>'qty_pcs')::int,'REBRAND',(v->>'physical_at')::timestamptz,'DRAFT',0,btrim(p_payload->>'reason'),erp.current_app_user_id());
 insert into erp.be_conversion_sources_v1(conversion_id,source_lot_id,origin_kind,rework_id,source_revision,created_by)
 values(p_request,l.id,p_origin,p_rework,v->>'source_revision',erp.current_app_user_id());
 perform erp.post_product_conversion(p_request);
 if p_payload ? 'expected_returns' then
   if jsonb_typeof(p_payload->'expected_returns') is distinct from 'array' or jsonb_array_length(p_payload->'expected_returns')>100 then
     raise exception 'BE_RETURN_LINES: maksimal 100 baris bongkaran';end if;
   for r in select value from jsonb_array_elements(p_payload->'expected_returns') loop
     perform erp._cp3_assert_closed_json_object(r,array['material_id','qty','holder'],array['material_id','qty','holder'],'bongkaran');
     v_material:=erp.bc_uuid_v1(r,'material_id',true);v_qty:=erp.bc_parse_qty_v1(v_material,r->'qty','qty');
     insert into erp.bc_outstanding_returns_v1(source_kind,owner_kind,material_id,qty_expected,holder,reference)
     values('CONVERSION','COMPANY',v_material,v_qty,erp.bc_text_v1(r,'holder',true,120),'BE-'||p_request::text) returning id into v_return;
     i:=i+1;insert into erp.be_conversion_returns_v1(outstanding_id,conversion_id,line_no) values(v_return,p_request,i);
   end loop;
 end if;
 if v_legacy then
  insert into cp7_sku_conversion.members_v1(conversion_id,group_id,line_no)values(p_request,p_request,1);
  perform cp7_sku_conversion.finalize_valuation_v2(p_request);
  delete from cp7_sku_conversion.execution_v1 where backend_pid=pg_backend_pid()and transaction_id=txid_current()and group_id=p_request;
  v:=v_original_preview;
 end if;
 select destination_lot_id into strict v_dest from erp.product_conversion_allocations where conversion_id=p_request;
 return v||jsonb_build_object('conversion_id',p_request,'destination_lot_id',v_dest,'status','POSTED','pending_returns',i);
end;$function$

erp.be_reverse_conversion_v1(uuid,text):
CREATE OR REPLACE FUNCTION erp.be_reverse_conversion_v1(p_conversion uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_legacy uuid;v_own boolean:=false;v_revalue boolean:=false;v_status text;
begin
 perform erp.require_permission('warehouse.brand_conversion.reverse');perform erp.require_owner_admin();
 perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
 if not exists(select 1 from erp.be_conversion_sources_v1 where conversion_id=p_conversion) then raise exception 'BE_DOCUMENT_NOT_FOUND';end if;
 if exists(select 1 from erp.be_conversion_cost_sources_v1 s join erp.bc_documents_v1 d on d.id=s.document_id
     where s.conversion_id=p_conversion and d.status='POSTED') then raise exception 'BE_REVERSE_DEPENDANTS: batalkan dahulu sumber biaya/pemulihan';end if;
 if exists(select 1 from erp.be_conversion_returns_v1 s join erp.bc_return_lots_v1 l on l.outstanding_id=s.outstanding_id
     join erp.bc_documents_v1 d on d.id=l.document_id where s.conversion_id=p_conversion and d.status='POSTED') then
   raise exception 'BE_REVERSE_DEPENDANTS: batalkan dahulu penerimaan bongkaran';end if;
 select g.group_id into v_legacy from cp7_sku_conversion.legacy_groups_v4 g where g.group_id=p_conversion;
 if v_legacy is not null then
  if (select count(*)from cp7_sku_conversion.members_v1 where group_id=v_legacy)<>1
   or not exists(select 1 from cp7_sku_conversion.members_v1 m
    join cp7_sku_conversion.legacy_groups_v4 g on g.group_id=m.group_id
    join erp.be_conversion_sources_v1 s on s.conversion_id=m.conversion_id
    where m.group_id=v_legacy and m.conversion_id=p_conversion and m.line_no=1
     and s.source_lot_id=g.source_lot_id and s.origin_kind=g.origin_kind and s.rework_id is not distinct from g.rework_id)then
   raise exception 'CP7_SKU_LEGACY_MEMBER_NOT_EXACT';end if;
  if exists(select 1 from cp7_sku_conversion.execution_v1 where backend_pid=pg_backend_pid()and transaction_id=txid_current())then
   if not exists(select 1 from cp7_sku_conversion.execution_v1 where backend_pid=pg_backend_pid()and transaction_id=txid_current()
    and group_id=v_legacy and mode='REVERSE')then raise exception 'CP7_SKU_LEGACY_EXECUTION_CONFLICT';end if;
  else
   select status into strict v_status from erp.product_conversions where id=p_conversion for update;
   if v_status='REVERSED'then
    if not exists(select 1 from cp7_sku_conversion.valuation_postings_v2 where group_id=v_legacy and phase='REVERSE')then
     raise exception 'CP7_SKU_LEGACY_REVERSE_NOT_EXACT';end if;
   else
    perform cp7_sku_conversion.assert_group_inverse_capacity_v3(v_legacy);v_revalue:=true;
   end if;
   insert into cp7_sku_conversion.execution_v1(backend_pid,transaction_id,group_id,mode)
   values(pg_backend_pid(),txid_current(),v_legacy,'REVERSE');v_own:=true;
  end if;
 end if;
 perform cp7_sku_conversion.automatic_assert_native_v5(p_conversion,null,null,null);
 perform erp.reverse_product_conversion(p_conversion,p_reason);
 update erp.bc_outstanding_returns_v1 set status='CANCELLED' where id in(select outstanding_id from erp.be_conversion_returns_v1 where conversion_id=p_conversion);
 if v_own then
  if v_revalue then perform cp7_sku_conversion.reverse_valuation_v2(v_legacy);end if;
  delete from cp7_sku_conversion.execution_v1 where backend_pid=pg_backend_pid()and transaction_id=txid_current()and group_id=v_legacy;
 end if;
end;$function$

erp.be_reverse_rework_target_v1(uuid,tex:
CREATE OR REPLACE FUNCTION erp.be_reverse_rework_target_v1(p_rework uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v uuid;v_own boolean;
begin
 if not exists(select 1 from erp.be_rework_targets_v1 where rework_id=p_rework) then return;end if;
 v_own:=not erp.be_in_context_v1();
 if v_own then insert into erp.be_execution_context_v1(backend_pid,transaction_id,request_id) values(pg_backend_pid(),txid_current(),gen_random_uuid());end if;
 for v in select s.conversion_id from erp.be_conversion_sources_v1 s join erp.product_conversions c on c.id=s.conversion_id
    where s.rework_id=p_rework and c.status='POSTED' order by c.physical_at desc,c.id desc loop
   perform cp7_sku_conversion.automatic_enter_v5(p_rework,'REVERSE',v);
   perform erp.be_reverse_conversion_v1(v,p_reason);
   perform cp7_sku_conversion.automatic_leave_v5(p_rework,'REVERSE',v);
 end loop;
 if v_own then delete from erp.be_execution_context_v1 where backend_pid=pg_backend_pid() and transaction_id=txid_current();end if;
end;$function$

cp7_sku_conversion.pool_quote_v2(uuid,uu:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.pool_quote_v2(p_product uuid, p_location uuid, p_grade text DEFAULT 'GRADE_A'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare v_qty numeric(20,6);v_base numeric(24,6);v_adjust numeric(24,6);v_value numeric(24,6);v_attr numeric(24,6);v_unknown boolean;v_revision text;
begin
 if p_product is null or p_location is null or p_grade is distinct from 'GRADE_A' then raise exception 'CP7_SKU_VALUE_SCOPE_REQUIRED';end if;
 with components as materialized(
  select c.*,h.cost_state,l.po_id root_po_id
  from cp7_sku_conversion.pool_components_v2(p_product,p_location,p_grade)c
  join erp.fg_lots l on l.id=c.root_lot_id
  left join erp.hpp_versions h on h.id=c.hpp_version_id
 ), totals as(
  select coalesce(sum(component_units),0)::numeric qty,coalesce(sum(value),0)::numeric value,
   coalesce(bool_or(component_units< -0.000000000001 or hpp_version_id is null or unit_value is null or cost_state='ESTIMATED'
    or erp.bd_lot_laundry_unknown_v1(root_lot_id)
    or(root_po_id is not null and not exists(select 1 from erp.get_hpp_completeness(root_po_id)z where z.pending_reason_count=0))),false) unknown
  from components
 )select qty,round(value,6),unknown into v_qty,v_value,v_unknown from totals;
 if v_unknown then raise exception 'CP7_SKU_POOL_HPP_UNKNOWN: seluruh komponen ekonomi termasuk reservasi harus diketahui';end if;
 v_base:=v_value;
 select coalesce(sum(c.value),0)into v_adjust from cp7_sku_conversion.pool_cost_components_v3(p_product,p_location,p_grade)c;
 v_value:=round(v_base+v_adjust,6);
 if v_value<0 then raise exception 'CP7_SKU_POOL_VALUE_NEGATIVE: nilai efektif persediaan tidak boleh negatif';end if;
 select coalesce(sum(a.value),0)into v_attr from cp7_sku_conversion.pool_attribution_v2(p_product,p_location,p_grade)a;
 if round(v_attr,6)is distinct from v_value then raise exception 'CP7_SKU_POOL_ATTRIBUTION_MISMATCH';end if;
 select md5(jsonb_build_object('product',p_product,'location',p_location,'grade',p_grade,'qty',v_qty,'base',v_base,'adjust',v_adjust,
  'components',(select coalesce(jsonb_agg(to_jsonb(c)order by c.root_lot_id),'[]'::jsonb)
   from cp7_sku_conversion.pool_components_v2(p_product,p_location,p_grade)c),
  'cost_components',(select coalesce(jsonb_agg(to_jsonb(c)order by c.root_lot_id),'[]'::jsonb)
   from cp7_sku_conversion.pool_cost_components_v3(p_product,p_location,p_grade)c),
  'cost_events',(select coalesce(jsonb_agg(to_jsonb(e)order by e.recorded_at,e.id),'[]'::jsonb)
   from cp7_sku_conversion.cost_events_v3 e where e.product_id=p_product and e.location_id=p_location and e.quality_grade=p_grade),
  'base_money',(select coalesce(jsonb_agg(to_jsonb(m)order by m.id),'[]')from cp7_sku_conversion.base_money_events_v4 m
   where m.root_lot_id in(select root_lot_id from cp7_sku_conversion.pool_components_v2(p_product,p_location,p_grade))),
  'events',(select coalesce(jsonb_agg(to_jsonb(e)order by e.recorded_at,e.id),'[]'::jsonb)from cp7_sku_conversion.valuation_events_v2 e
   where e.product_id=p_product and e.location_id=p_location and e.quality_grade=p_grade))::text) into v_revision;
 return jsonb_build_object('state',case when v_qty=0 then 'EMPTY' else 'KNOWN'end,'qty',v_qty::text,'value',v_value::text,
  'average',case when v_qty>0 then (v_value/v_qty)::text end,'base_value',v_base::text,'adjustment',v_adjust::text,
  'reserved_included',true,'basis','SKU_LOCATION_GRADE_MOVING_AVERAGE_V2','revision',v_revision);
end $function$

cp7_sku_conversion.post_conversion_money:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.post_conversion_money_v3(p_group uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare q cp7_sku_conversion.valuation_quotes_v2%rowtype;c record;cell record;old_units numeric;
 economic_date date;product uuid;
begin
 perform erp.require_internal();perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
 select *into strict q from cp7_sku_conversion.valuation_quotes_v2 where group_id=p_group;
 economic_date:=(q.physical_at at time zone 'Asia/Jakarta')::date;
 for c in select *from cp7_sku_conversion.cost_contributors_v3 where group_id=p_group and po_id is null order by root_lot_id loop
  select *into strict cell from cp7_sku_conversion.cost_money_cells_v3(c.root_lot_id)where product_id=q.source_product_id;
  -- Cost units have just moved; the money still belongs to the old source.
  old_units:=cell.units+c.transfer_units;
  if old_units<=0 or c.transfer_units>old_units
   or(c.transfer_units=old_units and c.transfer_value is distinct from cell.amount)
   or(cell.amount>=0 and(c.transfer_value<0 or c.transfer_value>cell.amount))
   or(cell.amount<0 and(c.transfer_value>0 or c.transfer_value<cell.amount))then
   raise exception 'CP7_SKU_COST_MONEY_TRANSFER_CAPACITY';end if;
  insert into cp7_sku_conversion.cost_money_events_v3(id,kind,source_id,root_lot_id,product_id,amount_delta,revision,source_proof,economic_date)
  values(gen_random_uuid(),'TRANSFER',p_group,c.root_lot_id,q.source_product_id,-c.transfer_value,p_group::text,to_jsonb(c),economic_date),
        (gen_random_uuid(),'TRANSFER',p_group,c.root_lot_id,q.target_product_id,c.transfer_value,p_group::text,to_jsonb(c),economic_date);
 end loop;
 for c in select a.*,l.po_id from cp7_sku_conversion.members_v1 m
  join erp.product_conversion_allocations a on a.conversion_id=m.conversion_id join erp.fg_lots l on l.id=a.destination_lot_id
  where m.group_id=p_group and l.po_id is null order by a.id loop
  insert into cp7_sku_conversion.cost_money_events_v3(id,kind,source_id,root_lot_id,product_id,amount_delta,revision,source_proof,economic_date)
  values(gen_random_uuid(),'ORIGIN',p_group,c.destination_lot_id,q.target_product_id,erp.be_allocation_extra_v1(c.id),
   p_group::text,jsonb_build_object('allocation',to_jsonb(c),'initial_extra',erp.be_allocation_extra_v1(c.id)),economic_date);
 end loop;
 for c in select distinct e.root_lot_id from cp7_sku_conversion.cost_events_v3 e where e.source_type='SKU_CONVERSION'and e.source_id=p_group loop
  perform cp7_sku_conversion.cost_current_unit_v3(c.root_lot_id,q.source_product_id);
  perform cp7_sku_conversion.cost_current_unit_v3(c.root_lot_id,q.target_product_id);
 end loop;
end $function$

erp.be_complete_rework_target_v1(uuid):
CREATE OR REPLACE FUNCTION erp.be_complete_rework_target_v1(p_rework uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b erp.be_rework_targets_v1%rowtype;r erp.rework_orders%rowtype;v_own boolean;v_result jsonb;
begin
 select * into b from erp.be_rework_targets_v1 where rework_id=p_rework;
 if b.rework_id is null then return;end if;
 select * into r from erp.rework_orders where id=p_rework for update;
 if not r.cost_posted or r.status<>'COMPLETED' then raise exception 'BE_REWORK_NOT_COMPLETE';end if;
 if r.qty_good_returned=0 then return;end if;
 if r.good_fg_lot_id is null then raise exception 'BE_REWORK_GOOD_LOT_MISSING';end if;
 if exists(select 1 from erp.be_conversion_sources_v1 s join erp.product_conversions c on c.id=s.conversion_id
      where s.rework_id=r.id and s.source_lot_id=r.good_fg_lot_id and c.status='POSTED') then return;end if;
 v_own:=not erp.be_in_context_v1();
 if v_own then insert into erp.be_execution_context_v1(backend_pid,transaction_id,request_id) values(pg_backend_pid(),txid_current(),gen_random_uuid());end if;
 v_result:=erp.be_post_conversion_v1(jsonb_build_object('source_lot_id',r.good_fg_lot_id,'target_product_id',b.target_product_id,
   'location_id',r.return_fg_location_id,'qty_pcs',r.qty_good_returned,'physical_at',r.completed_at,'reason',b.reason,
   'expected_version',erp.be_source_revision_v1(r.good_fg_lot_id,r.return_fg_location_id)),gen_random_uuid(),
   case when b.mode='REDYE_SKU' then 'REDYE' else 'REWORK' end,r.id);
 if v_own then delete from erp.be_execution_context_v1 where backend_pid=pg_backend_pid() and transaction_id=txid_current();end if;
end;$function$

erp.be_conversion_preview_v1(jsonb):
CREATE OR REPLACE FUNCTION erp.be_conversion_preview_v1(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare l erp.fg_lots%rowtype;s erp.products%rowtype;t erp.products%rowtype;v_location uuid;v_qty integer;
 v_at timestamptz;v_current numeric;v_dated numeric;v_hpp numeric;v_cost jsonb;v_source_pool jsonb;v_target_pool jsonb;
begin
 perform erp.require_permission('warehouse.brand_conversion.view');
 perform erp._cp3_assert_closed_json_object(p_payload,
   array['source_lot_id','target_product_id','location_id','qty_pcs','physical_at','reason','expected_version'],
   array['source_lot_id','target_product_id','location_id','qty_pcs','physical_at','reason','expected_version','expected_returns'],'konversi');
 perform erp.pocket_period_lock_v1();
 select * into l from erp.fg_lots where id=erp.bd_uuid_v1(p_payload,'source_lot_id',true);
 if l.id is null then raise exception 'BE_SOURCE_NOT_FOUND: lot sumber tidak ditemukan';end if;
 select * into s from erp.products where id=l.product_id for share;
 select * into t from erp.products where id=erp.bd_uuid_v1(p_payload,'target_product_id',true) for share;
 if t.id is null or not t.is_active then raise exception 'BE_TARGET_NOT_ACTIVE: SKU tujuan tidak aktif';end if;
 if t.id=s.id then raise exception 'BE_SAME_SKU: pilih SKU tujuan yang berbeda';end if;
 if not cp7_sku_conversion.manual_allocation_v1(l.id,t.id,(p_payload->>'location_id')::uuid,(p_payload->>'qty_pcs')::int,(p_payload->>'physical_at')::timestamptz) and (t.model_id is distinct from s.model_id or t.size_id is distinct from s.size_id) then
   raise exception 'BE_DIMENSION_MISMATCH: model konstruksi dan ukuran harus tetap';end if;
 v_location:=erp.bd_uuid_v1(p_payload,'location_id',true);
 v_qty:=erp.bd_qty_v1(p_payload->'qty_pcs','qty_pcs');
 v_at:=erp.bd_at_v1(p_payload->>'physical_at','physical_at');
 perform erp.bc_text_v1(p_payload,'reason',true,1000);
 if v_at<l.produced_at then raise exception 'BE_BEFORE_SOURCE: waktu konversi sebelum lot tersedia';end if;
 if v_at<s.effective_from then
  raise exception 'SKU % belum berlaku pada tanggal/jam transaksi %. Berlaku mulai %.',s.sku,v_at,s.effective_from;
 end if;
 if v_at<t.effective_from then
  raise exception 'SKU % belum berlaku pada tanggal/jam transaksi %. Berlaku mulai %.',t.sku,v_at,t.effective_from;
 end if;
 if t.effective_to is not null and v_at>=t.effective_to then
  raise exception 'Versi SKU % sudah berakhir pada %. Gunakan versi SKU yang berlaku pada tanggal/jam transaksi.',t.sku,t.effective_to;
 end if;
 if jsonb_typeof(p_payload->'expected_version') is distinct from 'string'
   or p_payload->>'expected_version' is distinct from erp.be_source_revision_v1(l.id,v_location) then
   raise exception 'STALE_VERSION: stok atau HPP sumber berubah; muat ulang';end if;
 select coalesce(sum(m.qty_signed),0),coalesce(sum(m.qty_signed) filter(where m.physical_at<=v_at),0)
   into v_current,v_dated from erp.fg_stock_movements m
   where m.lot_id=l.id and m.location_id=v_location and m.quality_grade='GRADE_A';
 if v_qty>least(v_current,v_dated) then raise exception 'BE_SOURCE_CAPACITY: jumlah melebihi stok sumber pada tanggalnya';end if;
 select hpp_per_pcs into v_hpp from erp.v_current_hpp where lot_id=l.id;
 if v_hpp is null then raise exception 'BE_SOURCE_HPP_UNKNOWN: nilai sumber belum diketahui';end if;
 v_cost:=case when erp.has_permission('finance.hpp.view') then
   jsonb_build_object('source_unit_hpp',v_hpp::text,'source_value',round(v_hpp*v_qty,2)::text) else '{}'::jsonb end;
 if not cp7_sku_conversion.manual_allocation_v1(l.id,t.id,v_location,v_qty,v_at)then
  v_source_pool:=cp7_sku_conversion.pool_quote_v2(s.id,v_location,'GRADE_A');
  v_target_pool:=cp7_sku_conversion.pool_quote_v2(t.id,v_location,'GRADE_A');
  if (v_source_pool->>'qty')::numeric<v_qty then raise exception 'CP7_SKU_INSUFFICIENT_VALUE_POOL: stok fisik bernilai tidak cukup';end if;
  if erp.has_permission('finance.hpp.view')then
   v_cost:=jsonb_build_object('source_unit_hpp',v_source_pool->>'average',
    'source_value',round(v_qty*(v_source_pool->>'average')::numeric,2)::text,
    'native_physical_value',round(v_hpp*v_qty,2)::text,'basis','SKU_LOCATION_GRADE_MOVING_AVERAGE_V2');
  end if;
 end if;
 return jsonb_build_object('source_lot_id',l.id,'source_product_id',s.id,'target_product_id',t.id,
   'source_sku',s.sku,'target_sku',t.sku,'location_id',v_location,'qty_pcs',v_qty,'physical_at',v_at,
   'source_revision',p_payload->>'expected_version','cost',v_cost)
  ||case when v_source_pool is null then '{}'::jsonb else jsonb_build_object(
   'source_value_revision',v_source_pool->>'revision','target_value_revision',v_target_pool->>'revision')end;
end;$function$

erp.be_post_conversion_v1(jsonb,uuid,tex:
CREATE OR REPLACE FUNCTION erp.be_post_conversion_v1(p_payload jsonb, p_request uuid, p_origin text DEFAULT 'FG'::text, p_rework uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v jsonb;l erp.fg_lots%rowtype;r jsonb;i integer:=0;v_return uuid;v_qty numeric;v_material uuid;v_dest uuid;v_legacy boolean;v_original_preview jsonb;v_native_request uuid;
begin
 perform erp.require_permission('warehouse.brand_conversion.post');
 if not erp.be_in_context_v1() then raise exception 'BE_FACADE_REQUIRED';end if;
 perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
 select * into l from erp.fg_lots where id=erp.bd_uuid_v1(p_payload,'source_lot_id',true) for update;
 v:=erp.be_conversion_preview_v1(p_payload);
 v_legacy:=not cp7_sku_conversion.manual_allocation_v1(l.id,(v->>'target_product_id')::uuid,
  (v->>'location_id')::uuid,(v->>'qty_pcs')::int,(v->>'physical_at')::timestamptz);
 if v_legacy then
  if exists(select 1 from cp7_sku_conversion.execution_v1 where backend_pid=pg_backend_pid()and transaction_id=txid_current())then
   raise exception 'CP7_SKU_LEGACY_EXECUTION_CONFLICT';end if;
  select request_id into strict v_native_request from erp.be_execution_context_v1
   where backend_pid=pg_backend_pid()and transaction_id=txid_current();
  v_original_preview:=v;
  insert into cp7_sku_conversion.groups_v1(request_id,actor,payload)values(p_request,erp.current_app_user_id(),p_payload);
  perform cp7_sku_conversion.prepare_valuation_v2(p_request,v);
  insert into cp7_sku_conversion.legacy_groups_v4(group_id,source_lot_id,origin_kind,rework_id,original_preview,
   native_request_id,admission_backend_pid,admission_transaction_id)
  values(p_request,l.id,p_origin,p_rework,v,v_native_request,pg_backend_pid(),txid_current());
  insert into cp7_sku_conversion.execution_v1(backend_pid,transaction_id,group_id,mode,source_lot_id,target_id,location_id,qty,physical_at)
  values(pg_backend_pid(),txid_current(),p_request,'POST',l.id,(v->>'target_product_id')::uuid,
   (v->>'location_id')::uuid,(v->>'qty_pcs')::int,(v->>'physical_at')::timestamptz);
  v:=jsonb_set(v,'{source_revision}',to_jsonb(erp.be_source_revision_v1(l.id,(v->>'location_id')::uuid)));
 end if;
 insert into erp.product_conversions(id,conversion_number,from_product_id,to_product_id,location_id,qty_pcs,conversion_type,
   physical_at,status,conversion_cost_total,notes,created_by)
 values(p_request,'BE-'||p_request::text,l.product_id,(v->>'target_product_id')::uuid,(v->>'location_id')::uuid,
   (v->>'qty_pcs')::int,'REBRAND',(v->>'physical_at')::timestamptz,'DRAFT',0,btrim(p_payload->>'reason'),erp.current_app_user_id());
 insert into erp.be_conversion_sources_v1(conversion_id,source_lot_id,origin_kind,rework_id,source_revision,created_by)
 values(p_request,l.id,p_origin,p_rework,v->>'source_revision',erp.current_app_user_id());
 perform erp.post_product_conversion(p_request);
 if p_payload ? 'expected_returns' then
   if jsonb_typeof(p_payload->'expected_returns') is distinct from 'array' or jsonb_array_length(p_payload->'expected_returns')>100 then
     raise exception 'BE_RETURN_LINES: maksimal 100 baris bongkaran';end if;
   for r in select value from jsonb_array_elements(p_payload->'expected_returns') loop
     perform erp._cp3_assert_closed_json_object(r,array['material_id','qty','holder'],array['material_id','qty','holder'],'bongkaran');
     v_material:=erp.bc_uuid_v1(r,'material_id',true);v_qty:=erp.bc_parse_qty_v1(v_material,r->'qty','qty');
     insert into erp.bc_outstanding_returns_v1(source_kind,owner_kind,material_id,qty_expected,holder,reference)
     values('CONVERSION','COMPANY',v_material,v_qty,erp.bc_text_v1(r,'holder',true,120),'BE-'||p_request::text) returning id into v_return;
     i:=i+1;insert into erp.be_conversion_returns_v1(outstanding_id,conversion_id,line_no) values(v_return,p_request,i);
   end loop;
 end if;
 if v_legacy then
  insert into cp7_sku_conversion.members_v1(conversion_id,group_id,line_no)values(p_request,p_request,1);
  perform cp7_sku_conversion.finalize_valuation_v2(p_request);
  delete from cp7_sku_conversion.execution_v1 where backend_pid=pg_backend_pid()and transaction_id=txid_current()and group_id=p_request;
  v:=v_original_preview;
 end if;
 select destination_lot_id into strict v_dest from erp.product_conversion_allocations where conversion_id=p_request;
 return v||jsonb_build_object('conversion_id',p_request,'destination_lot_id',v_dest,'status','POSTED','pending_returns',i);
end;$function$

erp.be_reverse_conversion_v1(uuid,text):
CREATE OR REPLACE FUNCTION erp.be_reverse_conversion_v1(p_conversion uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_legacy uuid;v_own boolean:=false;v_revalue boolean:=false;v_status text;
begin
 perform erp.require_permission('warehouse.brand_conversion.reverse');perform erp.require_owner_admin();
 perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
 if not exists(select 1 from erp.be_conversion_sources_v1 where conversion_id=p_conversion) then raise exception 'BE_DOCUMENT_NOT_FOUND';end if;
 if exists(select 1 from erp.be_conversion_cost_sources_v1 s join erp.bc_documents_v1 d on d.id=s.document_id
     where s.conversion_id=p_conversion and d.status='POSTED') then raise exception 'BE_REVERSE_DEPENDANTS: batalkan dahulu sumber biaya/pemulihan';end if;
 if exists(select 1 from erp.be_conversion_returns_v1 s join erp.bc_return_lots_v1 l on l.outstanding_id=s.outstanding_id
     join erp.bc_documents_v1 d on d.id=l.document_id where s.conversion_id=p_conversion and d.status='POSTED') then
   raise exception 'BE_REVERSE_DEPENDANTS: batalkan dahulu penerimaan bongkaran';end if;
 select g.group_id into v_legacy from cp7_sku_conversion.legacy_groups_v4 g where g.group_id=p_conversion;
 if v_legacy is not null then
  if (select count(*)from cp7_sku_conversion.members_v1 where group_id=v_legacy)<>1
   or not exists(select 1 from cp7_sku_conversion.members_v1 m
    join cp7_sku_conversion.legacy_groups_v4 g on g.group_id=m.group_id
    join erp.be_conversion_sources_v1 s on s.conversion_id=m.conversion_id
    where m.group_id=v_legacy and m.conversion_id=p_conversion and m.line_no=1
     and s.source_lot_id=g.source_lot_id and s.origin_kind=g.origin_kind and s.rework_id is not distinct from g.rework_id)then
   raise exception 'CP7_SKU_LEGACY_MEMBER_NOT_EXACT';end if;
  if exists(select 1 from cp7_sku_conversion.execution_v1 where backend_pid=pg_backend_pid()and transaction_id=txid_current())then
   if not exists(select 1 from cp7_sku_conversion.execution_v1 where backend_pid=pg_backend_pid()and transaction_id=txid_current()
    and group_id=v_legacy and mode='REVERSE')then raise exception 'CP7_SKU_LEGACY_EXECUTION_CONFLICT';end if;
  else
   select status into strict v_status from erp.product_conversions where id=p_conversion for update;
   if v_status='REVERSED'then
    if not exists(select 1 from cp7_sku_conversion.valuation_postings_v2 where group_id=v_legacy and phase='REVERSE')then
     raise exception 'CP7_SKU_LEGACY_REVERSE_NOT_EXACT';end if;
   else
    perform cp7_sku_conversion.assert_group_inverse_capacity_v3(v_legacy);v_revalue:=true;
   end if;
   insert into cp7_sku_conversion.execution_v1(backend_pid,transaction_id,group_id,mode)
   values(pg_backend_pid(),txid_current(),v_legacy,'REVERSE');v_own:=true;
  end if;
 end if;
 perform erp.reverse_product_conversion(p_conversion,p_reason);
 update erp.bc_outstanding_returns_v1 set status='CANCELLED' where id in(select outstanding_id from erp.be_conversion_returns_v1 where conversion_id=p_conversion);
 if v_own then
  if v_revalue then perform cp7_sku_conversion.reverse_valuation_v2(v_legacy);end if;
  delete from cp7_sku_conversion.execution_v1 where backend_pid=pg_backend_pid()and transaction_id=txid_current()and group_id=v_legacy;
 end if;
end;$function$

erp.be_reverse_rework_target_v1(uuid,tex:
CREATE OR REPLACE FUNCTION erp.be_reverse_rework_target_v1(p_rework uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v uuid;v_own boolean;
begin
 if not exists(select 1 from erp.be_rework_targets_v1 where rework_id=p_rework) then return;end if;
 v_own:=not erp.be_in_context_v1();
 if v_own then insert into erp.be_execution_context_v1(backend_pid,transaction_id,request_id) values(pg_backend_pid(),txid_current(),gen_random_uuid());end if;
 for v in select s.conversion_id from erp.be_conversion_sources_v1 s join erp.product_conversions c on c.id=s.conversion_id
    where s.rework_id=p_rework and c.status='POSTED' order by c.physical_at desc,c.id desc loop
   perform erp.be_reverse_conversion_v1(v,p_reason);
 end loop;
 if v_own then delete from erp.be_execution_context_v1 where backend_pid=pg_backend_pid() and transaction_id=txid_current();end if;
end;$function$
